import sys
from collections import Counter

def main():
    import sys
    import collections

    def readints():
        return list(map(int, sys.stdin.read().split()))

    data = readints()
    n = data[0]
    heights = data[1:]

    counter = collections.Counter(heights)
    max_freq = max(counter.values())
    most_common_heights = [height for height, freq in counter.items() if freq == max_freq]

    result = []
    for height in most_common_heights:
        current_circle = []
        for h in heights:
            if abs(h - height) <= 1:
                current_circle.append(h)

        if len(current_circle) > len(result):
            result = current_circle[:]

    print(len(result))
    print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()
